<?php defined('ABSPATH')||exit; function bluprint_archive_hero(){ $settings=bluprint_shop_archive_settings(); $is_shop=is_shop(); $term=!$is_shop?get_queried_object():null; $term_id=$term instanceof WP_Term?(int)$term->term_id:0; $term_image_id=$term_id?(int)get_term_meta($term_id,'thumbnail_id',true):0; $image_id=$is_shop?(int)$settings['image_left']:($term_image_id?: (int)$settings['image_left']); $title=$is_shop?$settings['title']:woocommerce_page_title(false); $description=$is_shop?$settings['description']:term_description(); $image_alt=$term_id?$term->name:$title; if($image_id){ $attachment_alt=get_post_meta($image_id,'_wp_attachment_image_alt',true); if($attachment_alt)$image_alt=$attachment_alt; } ?> <section class="bp-archive-hero bp-archive-hero--single"> <div class="bp-archive-hero__image bp-archive-hero__image--left"> <?php if($image_id)echo wp_get_attachment_image($image_id,'large',false,['alt'=>$image_alt,'loading'=>'eager','fetchpriority'=>'high','decoding'=>'async']);?> </div> <div class="bp-archive-hero__content"> <?php get_template_part('template-parts/components/breadcrumbs/breadcrumbs',null,['class'=>'bp-archive-breadcrumb']);?> <h1 dir="rtl"><?php echo esc_html($title);?></h1> <?php if($description):?> <div class="bp-archive-hero__description"><?php echo wp_kses_post(wpautop($description));?></div> <?php endif;?> </div> </section> <?php } function bluprint_archive_filter_sidebar(){ $f=bluprint_archive_filter_args(); $cats=bluprint_archive_filter_terms('product_cat'); $brands=bluprint_archive_filter_terms('product_brand'); $current=is_tax('product_cat')?get_queried_object_id():0; $bounds=bluprint_archive_price_bounds(); $min_value=$f['min']!==''?max($bounds['min'],min((float)$f['min'],$bounds['max'])):$bounds['min']; $max_value=$f['max']!==''?max($bounds['min'],min((float)$f['max'],$bounds['max'])):$bounds['max']; if($min_value>$max_value){ $min_value=$bounds['min']; $max_value=$bounds['max']; } $format_price=static function($value){ return number_format((float)$value,0,'.',','); }; ?> <form class="bp-archive-filters" method="get" action="<?php echo esc_url(bluprint_archive_base_url());?>"> <div class="bp-archive-filters__head"> <h2>فیلتر محصولات</h2> <button type="button" class="bp-filter-close" aria-label="بستن فیلترها">×</button> </div> <section class="bp-filter-group"> <h3>دسته‌بندی محصولات</h3> <div class="bp-filter-options bp-filter-options--scroll bp-filter-options--categories"> <?php foreach($cats as $term):?> <label class="bp-filter-category" style="--term-depth:<?php echo (int)($term->depth??0);?>"> <input type="checkbox" name="filter_category[]" value="<?php echo esc_attr($term->term_id);?>" <?php checked(in_array((int)$term->term_id,$f['cats'],true)||$current===(int)$term->term_id);?>> <span> <?php echo esc_html($term->name);?> <small>(<?php echo number_format_i18n($term->count);?>)</small> </span> </label> <?php endforeach;?> </div> </section> <section class="bp-filter-group bp-filter-price"> <h3>محدوده قیمت (تومان)</h3> <div class="bp-price-slider" data-price-slider style="--range-start:0%;--range-end:100%"> <div class="bp-price-slider__track"></div> <input type="range" name="min_price" data-price-min min="<?php echo esc_attr($bounds['min']);?>" max="<?php echo esc_attr($bounds['max']);?>" step="<?php echo esc_attr($bounds['step']);?>" value="<?php echo esc_attr($min_value);?>" aria-label="حداقل قیمت"> <input type="range" name="max_price" data-price-max min="<?php echo esc_attr($bounds['min']);?>" max="<?php echo esc_attr($bounds['max']);?>" step="<?php echo esc_attr($bounds['step']);?>" value="<?php echo esc_attr($max_value);?>" aria-label="حداکثر قیمت"> </div> <div class="bp-price-values"> <span>از <b data-price-min-value><?php echo esc_html($format_price($min_value));?></b> تومان</span> <span>تا <b data-price-max-value><?php echo esc_html($format_price($max_value));?></b> تومان</span> </div> </section> <?php if($brands):?> <section class="bp-filter-group"> <h3>برند</h3> <div class="bp-filter-options"> <?php foreach($brands as $term):?> <label> <input type="checkbox" name="filter_brand[]" value="<?php echo esc_attr($term->term_id);?>" <?php checked(in_array((int)$term->term_id,$f['brands'],true));?>> <span><?php echo esc_html($term->name);?> <small>(<?php echo number_format_i18n($term->count);?>)</small></span> </label> <?php endforeach;?> </div> </section> <?php endif;?> <section class="bp-filter-group bp-filter-stock"> <h3>موجودی</h3> <label> <input type="checkbox" name="stock_status" value="instock" <?php checked($f['stock']);?>> <span>فقط کالاهای موجود</span> </label> </section> <div class="bp-filter-actions"> <button class="bp-filter-apply" type="submit">اعمال فیلتر</button> <a href="<?php echo esc_url(bluprint_archive_base_url());?>">حذف فیلترها</a> </div> </form> <?php } function bluprint_archive_toolbar(){ global $wp_query; $count=(int)$wp_query->found_posts; $from=$count?((max(1,get_query_var('paged'))-1)*24+1):0; $to=min($count,$from+24-1); ?> <div class="bp-archive-toolbar"> <p>نمایش <?php echo number_format_i18n($from);?> تا <?php echo number_format_i18n($to);?> از <?php echo number_format_i18n($count);?> محصول</p> <div class="bp-archive-toolbar__controls"> <button class="bp-filter-open" type="button" aria-expanded="false" aria-controls="bp-archive-filter-panel"> <svg class="bp-filter-open__icon" xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"> <path d="M4 7h16M7 12h10m-7 5h4"/> <circle cx="8" cy="7" r="1.5" fill="currentColor" stroke="none"/> <circle cx="15" cy="12" r="1.5" fill="currentColor" stroke="none"/> <circle cx="12" cy="17" r="1.5" fill="currentColor" stroke="none"/> </svg> <span>فیلتر محصولات</span> </button> <?php woocommerce_catalog_ordering();?> </div> </div> <?php } function bluprint_archive_content(){
    $is_rich=false;

    if(is_shop()){
        $content=bluprint_shop_archive_settings()['content'];
    }else{
        $term=get_queried_object();
        $content=$term instanceof WP_Term&&function_exists('bluprint_get_term_content')?bluprint_get_term_content($term->term_id):'';

        if(trim(wp_strip_all_tags($content))!==''){
            $is_rich=true;
        }else{
            $content=$term instanceof WP_Term?term_description($term):'';
        }
    }

    if(!$content)return;

    $classes='bp-archive-content'.($is_rich?' bp-archive-content--rich':'');
    $body_classes='bp-archive-content__body'.($is_rich?' bp-post__content entry-content':'');
    ?>
    <section class="<?php echo esc_attr($classes); ?>">
        <div class="<?php echo esc_attr($body_classes); ?>" data-archive-content><?php echo wp_kses_post($content); ?></div>
        <button type="button" class="bp-archive-content__toggle" data-archive-toggle aria-expanded="false">ادامه مطلب</button>
    </section>
    <?php
} function bluprint_render_product_archive(){ if(!function_exists('WC'))return; get_header('shop'); ?> <main id="main-content" class="bp-archive container"> <?php bluprint_archive_hero();?> <div class="bp-archive-layout"> <div class="bp-archive-main"> <?php bluprint_archive_toolbar();?> <?php if(woocommerce_product_loop()):?> <div class="bp-archive-grid"> <?php while(have_posts()):the_post();global $product;get_template_part('template-parts/components/cards/product-card',null,['product'=>$product]);endwhile;?> </div> <?php woocommerce_pagination();?> <?php else:?> <?php do_action('woocommerce_no_products_found');?> <?php endif;?> </div> <aside class="bp-archive-sidebar" id="bp-archive-filter-panel"> <?php bluprint_archive_filter_sidebar();?> </aside> </div> <?php bluprint_archive_content();?> </main> <?php get_footer('shop'); }